INSERT OR IGNORE INTO resources(id,title,summary,body,category_id,tags,format,size,status,featured,demo,updated_at) VALUES
('demo-resume','一份清爽的个人简历模板','适合应届求职与职场转型，整理经历，从一张清楚的简历开始。','## 这是一份演示资料\n\n这条内容用于展示资源详情页，没有真实网盘链接。\n\n## 正式发布时可以补充\n\n- 模板包含的页数与格式\n- 推荐使用的编辑工具\n- 使用说明与预览图片','office','求职,简历','DOCX','', 'published',1,1,'2026-09-13T03:00:00Z'),
('demo-ai','AI 提示词整理手册','把写作、阅读与日常办公中的常见问题，整理成可以反复使用的提问方式。','## 内容预览\n\n这是一条演示资源，用于体验网站。正式资源可以在这里添加章节目录、适用对象和使用方法。\n\n## 可以如何使用\n\n- 从一个具体问题开始\n- 写清目标与背景\n- 保存经过验证的提问方式','ai','AI,提示词','PDF','', 'published',1,1,'2026-09-12T03:00:00Z'),
('demo-plan','每周学习计划与复盘表','把大目标拆成一周能完成的小事，用简单的记录看见自己的进步。','## 适合谁\n\n正在准备考试、学习一门新技能，或希望保持学习节奏的朋友。\n\n## 演示说明\n\n这是一条用于展示分类与详情页面的演示资料，暂未添加网盘入口。','learning','计划,自我提升','XLSX','', 'published',1,1,'2026-09-11T03:00:00Z'),
('demo-color','日常设计配色参考集','收集克制、耐看的配色方向，为演示文稿和内容排版提供一些灵感。','## 关于这份资料\n\n这是网站演示条目，没有真实下载资源。\n\n## 发布建议\n\n正式发布时，请添加自己制作或有权分享的素材，说明适用范围与格式。','design','配色,灵感','PDF','', 'published',0,1,'2026-09-10T03:00:00Z'),
('demo-shortcuts','常用快捷键速查清单','少一次寻找菜单，多一点专注。为常见桌面操作整理一份随手可查的清单。','## 演示资料\n\n本条目展示工具类资源在网站中的样式。\n\n## 正式内容可以包含\n\n- 系统操作快捷键\n- 文档编辑快捷键\n- 浏览器快捷键','tools','快捷键,效率','PDF','', 'published',0,1,'2026-09-09T03:00:00Z'),
('demo-budget','个人收支记录表','从每一笔小支出开始，整理每月收入、预算和储蓄计划。','## 演示资料\n\n这是演示条目，没有真实网盘链接。\n\n## 内容介绍\n\n实际发布时可以填写表格结构、使用方法、文件格式及注意事项。','office','表格,生活','XLSX','', 'published',0,1,'2026-09-08T03:00:00Z');
